    rwa: ["RWA\xB7\uD1A0\uD070\uD654", "\uD1A0\uD070\uD654 \uAD6D\uCC44, \uC8FC\uC2DD \uB4F1 \uC2E4\uBB3C \uC790\uC0B0\uC758 \uAD6C\uC870, \uC811\uADFC \uADDC\uCE59, \uC218\uC775 \uB4A4\uC758 \uC704\uD5D8\uC744 \uC5F0\uAD6C\uD569\uB2C8\uB2E4."],
    research: ["\uCD9C\uCC98 \uAE30\uBC18 \uB9AC\uC11C\uCE58", "\uC2DC\uC7A5 \uAD6C\uC870, \uAC70\uB798\uC18C \uC6B4\uC601, \uAC70\uB798 \uBE44\uC6A9\uC5D0 \uAD00\uD55C \uC2EC\uCE35 \uB9AC\uC11C\uCE58\uB85C \uAC01 \uAE30\uC0AC \uD558\uB2E8\uC5D0 \uCD9C\uCC98\uB97C \uD45C\uC2DC\uD569\uB2C8\uB2E4."]
