var SECTION_EYEBROW_LOCALES = Object.freeze(Object.keys(LABELS2));
function labelsFor(locale) {
  const value = String(locale || "en");
  if (LABELS2[value]) return LABELS2[value];
  if (value.toLowerCase() === "pt-br" || value.startsWith("pt")) return LABELS2["pt-BR"];
  if (value === "zh-TW" || value === "zh-HK" || value === "zh-Hant") return LABELS2["zh-Hant"];
  if (value.startsWith("zh")) return LABELS2["zh-Hans"];
  return LABELS2[value.split("-")[0]] || LABELS2.en;
}
function sectionEyebrow(locale, key2) {
  const label = labelsFor(locale)[key2];
  return label ? `NEXUALPHA \xB7 ${label}` : void 0;
}
function sectionEyebrowAttrs(locale, key2) {
  const text = sectionEyebrow(locale, key2);
  if (!text) return {};
  return { "data-eyebrow": text, style: { "--section-eyebrow": JSON.stringify(text) } };
}

