var slugOf = (venue2) => typeof venue2 === "string" ? venue2 : venue2?.slug || venue2?.partner || venue2?.id;
var rank = (venue2) => {
  const index = VENUE_PRIORITY.indexOf(slugOf(venue2));
  return index < 0 ? VENUE_PRIORITY.length : index;
};
var compareVenuePriority = (a, b) => rank(a) - rank(b);
function orderVenues(venues = [], locale = "en") {
  return [...venues].filter((venue2) => !/^tr(?:-|$)/i.test(locale) || slugOf(venue2) !== "bitget").sort(compareVenuePriority);
}

