  ru: "\u0412\u0430\u0448\u0438 \u043A\u043E\u043C\u0438\u0441\u0441\u0438\u0438 \u2014 \u043E\u0431\u0440\u0430\u0442\u043D\u043E. \u0414\u043E {max}.",
