function promotionCopy(locale = "en") {
  const key2 = Object.keys(rows).find((key3) => key3.toLowerCase() === String(locale).toLowerCase());
  const [sponsored, tool, open, compare, conditions] = rows[key2] || rows.en;
  return { sponsored, tool, open, compare, conditions };
}
var promotionConditions = Object.fromEntries(Object.keys(rows).map((locale) => [locale, promotionCopy(locale).conditions]));

