function newsSignupBridge({ articleSlug, locale = "en", market, venueName, hasVenue }) {
  const venue2 = registrationVenueForArticle(articleSlug, hasVenue);
  if (!venue2) return null;
  const name = venueName?.(venue2) || venue2;
  const neutral = WALLET_VENUES.has(venue2) || NEUTRAL_LOCALES.has(locale) || !SIGNUP_COPY[locale] || !isPartnerPromotableIn(venue2, { locale, market });
  const profileHref = `/exchanges/${venue2}`;
  if (neutral) {
    return { venue: venue2, neutral: true, eyebrow: null, links: [{ kind: "profile", href: profileHref, label: (PROFILE_COPY[locale] || PROFILE_COPY.en)(name) }] };
  }
  const copy3 = SIGNUP_COPY[locale];
  const links = [{ kind: "profile", href: CODES[venue2] ? `${profileHref}#registration-path` : profileHref, label: copy3.guide(name, CODES[venue2] || null) }];
  if (APP_DOWNLOAD_SLUGS.includes(venue2)) links.push({ kind: "app", href: appDownloadPath(venue2), label: copy3.app(name) });
  return { venue: venue2, neutral: false, eyebrow: copy3.eyebrow, links };
}
