var LINK_SEPARATOR = Object.freeze({ "zh-Hans": "\uFF1A", "zh-Hant": "\uFF1A", ja: "\uFF1A", fr: " : " });
function isArticleEmbedLine(line) {
  return ANY_EMBED_LINE.test(String(line ?? ""));
}
function parseArticleEmbed(block) {
  const text = String(block ?? "").trim();
  if (!isArticleEmbedLine(text) || text.includes("\n")) return null;
  const match = text.match(ARTICLE_EMBED_LINE);
  const kind = match ? ALIASES[match[1].toLowerCase()] || null : null;
  if (!kind) return { kind: null, symbol: null };
  const symbol = ARTICLE_EMBED_KINDS[kind].symbolParam && match[2] ? match[2].toUpperCase() : null;
  return { kind, symbol };
}
var embedLocale = (locale) => Object.hasOwn(ARTICLE_EMBED_COPY, locale) ? locale : String(locale || "").startsWith("zh") ? "zh-Hans" : "en";
function articleEmbedModel(directive, locale = "en") {
  const kind = directive?.kind;
  const spec = kind ? ARTICLE_EMBED_KINDS[kind] : null;
  if (!spec) return null;
  const loc = embedLocale(locale);
  const copy3 = ARTICLE_EMBED_COPY[loc];
  const query = new URLSearchParams({ locale: loc, theme: "dark" });
  if (directive.symbol) query.set("symbol", directive.symbol);
  return {
    kind,
    symbol: directive.symbol || null,
    src: `/embed/${kind}?${query.toString()}`,
    height: spec.height,
    title: `${copy3[kind]} \u2014 NexuAlpha`,
    caption: copy3.live,
    toolHref: `${LOCALE_PREFIX[loc]}${spec.toolPath}`,
    toolLabel: copy3.open,
    toolName: copy3[kind],
    // "Open the full page: <tool>" with the locale's colon (full-width in CJK, spaced in French).
    toolLinkText: `${copy3.open}${LINK_SEPARATOR[loc] || ": "}${copy3[kind]}`
  };
}
function stripArticleEmbedDirectives(text) {
  return String(text ?? "").split("\n").filter((line) => !isArticleEmbedLine(line)).join("\n");
}
function isolateArticleEmbedDirectives(markdown) {
  const lines = String(markdown ?? "").split("\n");
  if (!lines.some((line) => isArticleEmbedLine(line))) return String(markdown ?? "");
  const out2 = [];
  for (const line of lines) {
    if (isArticleEmbedLine(line)) {
      if (out2.length && out2[out2.length - 1].trim() !== "") out2.push("");
      out2.push(line.trim(), "");
    } else {
      if (line.trim() === "" && out2.length && out2[out2.length - 1] === "") continue;
      out2.push(line);
    }
  }
  return out2.join("\n");
}

