  ja: ["\u6E96\u5099\u91D1\u8A3C\u660E\uFF08PoR\uFF09\u306E\u78BA\u8A8D\u30AC\u30A4\u30C9\uFF1A\u53D6\u5F15\u6240\u306E\u691C\u8A3C\u65B9\u6CD5", (n) => `\u53D6\u5F15\u6240\u306E\u6E96\u5099\u91D1\u8A3C\u660E\uFF08PoR\uFF09\u30EC\u30DD\u30FC\u30C8\u306E\u8AAD\u307F\u65B9\u3092\u624B\u9806\u3067\u89E3\u8AAC\u3057\u3001${n}\u53D6\u5F15\u6240\u306E\u516C\u5F0F\u30DA\u30FC\u30B8\u3092\u63B2\u8F09\u3002\u6E96\u5099\u91D1\u5831\u544A\u306F\u652F\u6255\u80FD\u529B\u306E\u4FDD\u8A3C\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002`],
  ko: ["\uC900\uBE44\uAE08 \uC99D\uBA85(PoR) \uD655\uC778 \uAC00\uC774\uB4DC: \uAC70\uB798\uC18C \uAC80\uC99D \uBC29\uBC95", (n) => `\uAC70\uB798\uC18C \uC900\uBE44\uAE08 \uC99D\uBA85(PoR) \uBCF4\uACE0\uC11C \uC77D\uB294 \uBC95\uACFC ${n}\uAC1C \uAC70\uB798\uC18C \uACF5\uC2DD \uB9C1\uD06C. \uC900\uBE44\uAE08 \uBCF4\uACE0\uC11C\uB294 \uC9C0\uAE09 \uB2A5\uB825\uC774\uB098 \uC548\uC804\uC744 \uBCF4\uC7A5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.`],
  es: ["Prueba de reservas: c\xF3mo verificar un exchange cripto", (n) => `Gu\xEDa paso a paso para leer el informe de prueba de reservas de un exchange, con enlaces oficiales de ${n} plataformas. No es una garant\xEDa de solvencia.`],
  "pt-BR": ["Prova de reservas: como verificar uma exchange cripto", (n) => `Guia passo a passo para ler o relat\xF3rio de prova de reservas de uma exchange, com links oficiais de ${n} plataformas. N\xE3o \xE9 garantia de solv\xEAncia.`],
  fr: ["Preuve de r\xE9serves : v\xE9rifier une plateforme crypto", (n) => `Guide pas \xE0 pas pour lire le rapport de preuve de r\xE9serves d\u2019une plateforme, avec les liens officiels de ${n} plateformes. Pas une garantie de solvabilit\xE9.`],
  de: ["Proof of Reserves: Krypto-B\xF6rsen richtig pr\xFCfen", (n) => `Schritt f\xFCr Schritt einen Proof-of-Reserves-Bericht lesen, mit offiziellen Links zu ${n} B\xF6rsen. Reserveberichte sind keine Garantie f\xFCr Solvenz.`],
  it: ["Proof of reserves: come verificare un exchange crypto", (n) => `Guida passo passo alla lettura del report proof of reserves di un exchange, con i link ufficiali di ${n} piattaforme. Non \xE8 una garanzia di solvibilit\xE0.`],
  ru: ["Proof of Reserves: \u043A\u0430\u043A \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u043A\u0440\u0438\u043F\u0442\u043E\u0431\u0438\u0440\u0436\u0443", (n) => `\u041F\u043E\u0448\u0430\u0433\u043E\u0432\u043E\u0435 \u0440\u0443\u043A\u043E\u0432\u043E\u0434\u0441\u0442\u0432\u043E \u043F\u043E \u0447\u0442\u0435\u043D\u0438\u044E \u043E\u0442\u0447\u0451\u0442\u0430 proof of reserves \u0438 \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 ${n} \u0431\u0438\u0440\u0436. \u041E\u0442\u0447\u0451\u0442 \u043E \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0445 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0440\u0443\u0435\u0442 \u043F\u043B\u0430\u0442\u0451\u0436\u0435\u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u044C.`],
  tr: ["Rezerv kan\u0131t\u0131: Bir kripto borsas\u0131 nas\u0131l do\u011Frulan\u0131r", (n) => `Bir borsan\u0131n rezerv kan\u0131t\u0131 (PoR) raporunu ad\u0131m ad\u0131m okuma rehberi ve ${n} borsan\u0131n resm\xEE ba\u011Flant\u0131lar\u0131. Rezerv raporu \xF6deme g\xFCc\xFC garantisi de\u011Fildir.`],
  id: ["Proof of reserves: cara memverifikasi exchange kripto", (n) => `Panduan langkah demi langkah membaca laporan proof of reserves exchange, dengan tautan resmi ${n} platform. Laporan cadangan bukan jaminan solvabilitas.`],
  vi: ["B\u1EB1ng ch\u1EE9ng d\u1EF1 tr\u1EEF: c\xE1ch ki\u1EC3m tra m\u1ED9t s\xE0n crypto", (n) => `H\u01B0\u1EDBng d\u1EABn t\u1EEBng b\u01B0\u1EDBc \u0111\u1ECDc b\xE1o c\xE1o b\u1EB1ng ch\u1EE9ng d\u1EF1 tr\u1EEF (PoR) c\u1EE7a s\xE0n, k\xE8m li\xEAn k\u1EBFt ch\xEDnh th\u1EE9c c\u1EE7a ${n} s\xE0n. B\xE1o c\xE1o d\u1EF1 tr\u1EEF kh\xF4ng \u0111\u1EA3m b\u1EA3o kh\u1EA3 n\u0103ng thanh to\xE1n.`],
  ar: ["\u0625\u062B\u0628\u0627\u062A \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A: \u0643\u064A\u0641 \u062A\u062A\u062D\u0642\u0642 \u0645\u0646 \u0645\u0646\u0635\u0629 \u062A\u062F\u0627\u0648\u0644", (n) => `\u062F\u0644\u064A\u0644 \u062E\u0637\u0648\u0629 \u0628\u062E\u0637\u0648\u0629 \u0644\u0642\u0631\u0627\u0621\u0629 \u062A\u0642\u0631\u064A\u0631 \u0625\u062B\u0628\u0627\u062A \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A \u0644\u062F\u0649 \u0627\u0644\u0645\u0646\u0635\u0629\u060C \u0645\u0639 \u0631\u0648\u0627\u0628\u0637 \u0631\u0633\u0645\u064A\u0629 \u0644\u0640 ${n} \u0645\u0646\u0635\u0627\u062A. \u062A\u0642\u0631\u064A\u0631 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A \u0644\u064A\u0633 \u0636\u0645\u0627\u0646\u064B\u0627 \u0644\u0644\u0645\u0644\u0627\u0621\u0629 \u0623\u0648 \u0627\u0644\u0623\u0645\u0627\u0646.`],
  // l10n: needs native review
  ur: ["\u0630\u062E\u0627\u0626\u0631 \u06A9\u0627 \u062B\u0628\u0648\u062A: \u06A9\u0631\u067E\u0679\u0648 \u0627\u06CC\u06A9\u0633\u0686\u06CC\u0646\u062C \u06A9\u06CC \u062A\u0635\u062F\u06CC\u0642 \u06A9\u06CC\u0633\u06D2 \u06A9\u0631\u06CC\u06BA", (n) => `\u0630\u062E\u0627\u0626\u0631 \u06A9\u06CC \u0631\u067E\u0648\u0631\u0679 \u067E\u0691\u06BE\u0646\u06D2 \u06A9\u0627 \u0631\u06C1\u0646\u0645\u0627 \u0627\u0648\u0631 ${n} \u067E\u0644\u06CC\u0679 \u0641\u0627\u0631\u0645\u0632 \u06A9\u06CC \u0633\u0631\u06A9\u0627\u0631\u06CC \u0631\u067E\u0648\u0631\u0679\u0633 \u06A9\u06D2 \u0631\u0648\u0627\u0628\u0637\u06D4 \u0630\u062E\u0627\u0626\u0631 \u06A9\u0627 \u062B\u0628\u0648\u062A \u0627\u062F\u0627\u0626\u06CC\u06AF\u06CC \u06A9\u06CC \u0635\u0644\u0627\u062D\u06CC\u062A \u06A9\u06CC \u0636\u0645\u0627\u0646\u062A \u0646\u06C1\u06CC\u06BA\u06D4`],
  // l10n: needs native review
  uk: ["Proof of Reserves: \u044F\u043A \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u043A\u0440\u0438\u043F\u0442\u043E\u0431\u0456\u0440\u0436\u0443", (n) => `\u042F\u043A \u0447\u0438\u0442\u0430\u0442\u0438 \u0437\u0432\u0456\u0442 \u043F\u0440\u043E \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043D\u043D\u044F \u0440\u0435\u0437\u0435\u0440\u0432\u0456\u0432: \u043E\u0444\u0456\u0446\u0456\u0439\u043D\u0456 \u043F\u043E\u0441\u0438\u043B\u0430\u043D\u043D\u044F \u043D\u0430 ${n} \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C. \u0417\u0432\u0456\u0442\u0438 \u043F\u0440\u043E \u0440\u0435\u0437\u0435\u0440\u0432\u0438 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0443\u044E\u0442\u044C \u043F\u043B\u0430\u0442\u043E\u0441\u043F\u0440\u043E\u043C\u043E\u0436\u043D\u0456\u0441\u0442\u044C.`]
