    guarantee: "\u50A8\u5907\u8BC1\u660E\u53EA\u662F\u67D0\u4E00\u65F6\u70B9\u7684\u5FEB\u7167\uFF0C\u4E0D\u662F\u5BF9\u5168\u90E8\u8D1F\u503A\u7684\u5BA1\u8BA1\uFF1B\u5B83\u4E0D\u662F\u507F\u4ED8\u80FD\u529B\u6216\u8D44\u91D1\u5B89\u5168\u4FDD\u8BC1\uFF0C\u4E5F\u4E0D\u662F\u5B58\u6B3E\u4FDD\u9669\u3002\u5373\u4F7F\u62A5\u544A\u826F\u597D\uFF0C\u4EA4\u6613\u6240\u4ECD\u53EF\u80FD\u6682\u505C\u63D0\u73B0\u6216\u5012\u95ED\u3002",
