function matrixCopy(locale = "en") {
  const l = String(locale || "en");
  if (l === "zh-CN") return { ...T.en, ...T["zh-Hans"] };
  if (l === "zh-TW") return { ...T.en, ...T["zh-Hant"] };
  if (T[l]) return { ...T.en, ...T[l] };
  if (l.toLowerCase().startsWith("pt")) return { ...T.en, ...T["pt-BR"] };
  return { ...T.en, ...T[l.split("-")[0]] || {} };
}

