function venueProfile(venue2, locale = "en") {
  const text = v3Copy(locale);
  const brand = brandsBySlug[venue2.slug];
  const sources = sourceHubs[venue2.slug] ?? [];
  const sourceHost = sources[0] ? new URL(sources[0].url).host : "";
  const editorial = priorityProfiles[locale]?.[venue2.slug] ?? genericEditorial(venue2, locale, sources.length, text);
  const checks = uniqueTextEntries(editorial?.checks ?? text.checksByCategory[venue2.category] ?? text.checksByCategory.CEX);
  const checkKeys = new Set(checks.map(textEntryKey));
  return {
    ...venue2,
    officialDomain: venue2.officialDomain || "",
    sourceHost,
    positioning: editorial?.positioning ?? text.detailBody(venue2.name, venue2.category),
    useCases: editorial?.useCases ?? text.useCasesByCategory[venue2.category] ?? text.useCasesByCategory.CEX,
    checks,
    strengths: editorial.strengths,
    // Generic non-English profiles derive limitations from the same check list; never repeat a check (audit NX-07).
    limitations: uniqueTextEntries(editorial.limitations).filter((item) => !checkKeys.has(textEntryKey(item))),
    suggestedComparisons: editorial.suggestedComparisons,
    accessModel: text.accessByCategory[venue2.category] ?? text.accessByCategory.CEX,
    researchScope: text.verifiedOnly,
    sourceHubs: sources,
    brandAssetState: brand?.preferredSquare ? "RECORDED" : "PENDING",
    partnerCtaState: "CTA_NOT_CONFIGURED",
    activityState: "PENDING_REVIEW"
  };
}

