        "zh-Hans": "\u8FD9\u7BC7\u6587\u7AE0\u628A\u201C\u8DE8\u5883\u652F\u4ED8\u66F4\u5FEB\u201D\u62C6\u6210\u53EF\u6838\u9A8C\u7684\u76D1\u7BA1\u95EE\u9898\uFF1A\u8C01\u6CBB\u7406\u652F\u4ED8\u6865\u6216\u7A33\u5B9A\u5E01\u53D1\u884C\u65B9\uFF0C\u4F55\u65F6\u4EA7\u751F\u6CD5\u5F8B\u6700\u7EC8\u6027\uFF0C\u6280\u672F\u8FDE\u63A5\u662F\u5426\u7B49\u4E8E\u89C4\u5219\u4E92\u64CD\u4F5C\uFF0C\u4E8B\u6545\u4E2D\u662F\u5426\u6709\u97E7\u6027\u4E0E\u8FDE\u7EED\u6027\uFF0C\u5236\u88C1/AML \u4F1A\u4E0D\u4F1A\u51BB\u7ED3\u6216\u62D2\u7EDD\u4EA4\u6613\uFF0C\u4EE5\u53CA\u53D1\u884C\u65B9\u3001\u5E73\u53F0\u6216\u652F\u4ED8\u6865\u4E0D\u5728\u7528\u6237\u8F96\u533A\u65F6\uFF0C\u6295\u8BC9\u3001\u9000\u6B3E\u548C\u8FFD\u7D22\u8DEF\u5F84\u662F\u5426\u771F\u5B9E\u5B58\u5728\u3002"
