        "zh-Hans": "\u672C\u6587\u7528\u6765\u6E90\u6620\u5C04\u6838\u5BF9 \u5982\u4F55\u521B\u5EFA Gemini \u8D26\u6237\u3001\u5B8C\u6210\u8EAB\u4EFD\u9A8C\u8BC1\u5E76\u8BBE\u7F6E\u63D0\u5E01\u4FDD\u62A4 \u7684\u53EF\u884C\u52A8\u8FB9\u754C\uFF0C\u5148\u7ED9\u51FA\u7ED3\u8BBA\uFF0C\u518D\u4FDD\u7559\u672A\u77E5\u9879\u3002"
