        "zh-Hans": "\u5982\u4F55\u4F7F\u7528 Uniswap\uFF1A\u5B89\u5168\u8FDE\u63A5\u94B1\u5305\u5E76\u5B8C\u6210\u9996\u6B21 Swap"
