        "zh-Hans": "\u4EE3\u5E01\u5316 NMS \u80A1\u7968\u573A\u6240\u62AB\u9732\u96F7\u8FBE\uFF1A\u53D1\u884C\u4EBA\u901A\u77E5\u3001\u6743\u5229\u4E0E\u667A\u80FD\u5408\u7EA6"
