        "zh-Hans": "\u52A0\u5BC6\u4EA4\u6613\u6240\u884C\u60C5 Schema \u7248\u672C\u96F7\u8FBE\uFF1ASBE\u3001WebSocket \u4E0E\u91CD\u8FDE\u8BC1\u636E"
