        "zh-Hans": "\u6458\u8981\uFF1A\u672C\u6587\u7528\u5B98\u65B9\u6765\u6E90\u5EFA\u7ACB\u4E00\u5F20\u53EF\u6267\u884C\u7684\u98CE\u9669\u8FB9\u754C\u56FE\uFF0C\u5E2E\u52A9\u8BFB\u8005\u5148\u6838\u9A8C\u8BC1\u636E\u3001\u5BF9\u8C61\u3001\u7528\u6237\u72B6\u6001\u548C\u505C\u6B62\u6761\u4EF6\uFF0C\u518D\u51B3\u5B9A\u662F\u5426\u7EE7\u7EED\u3002"
