        "zh-Hans": "CFTC \u88AB\u52A8\u8F6F\u4EF6\u4E0D\u91C7\u53D6\u884C\u52A8\u96F7\u8FBE\uFF1A\u63A7\u5236\u3001\u6258\u7BA1\u4E0E\u6267\u884C\u8FB9\u754C"
