        "zh-Hans": "\u76F4\u63A5\u8BBF\u95EE backpack.exchange\uFF0C\u9009\u62E9\u6CE8\u518C\uFF0C\u586B\u5199\u672C\u4EBA\u63A7\u5236\u7684\u90AE\u7BB1\uFF0C\u8BBE\u7F6E\u552F\u4E00\u5BC6\u7801\uFF0C\u63A5\u53D7\u5F53\u524D\u534F\u8BAE\uFF0C\u5E76\u5728\u6709\u6548\u671F\u5185\u8F93\u5165\u90AE\u7BB1\u9A8C\u8BC1\u7801\u3002\u968F\u540E\u8FDB\u5165\u8EAB\u4EFD\u8BA4\u8BC1\uFF0C\u63D0\u4F9B\u5C45\u4F4F\u5730\u3001\u6CD5\u5B9A\u8EAB\u4EFD\u3001\u6536\u5165\u6765\u6E90\u3001\u8BC1\u4EF6\u56FE\u50CF\u5E76\u5B8C\u6210\u4EBA\u8138\u6D3B\u4F53\u68C0\u67E5\u3002\u901A\u8FC7\u540E\u542F\u7528\u53EF\u7528\u5B89\u5168\u63A7\u5236\uFF0C\u518D\u901A\u8FC7\u5145\u503C\u83DC\u5355\u8FDB\u884C\u7F51\u7EDC\u5339\u914D\u7684\u5C0F\u989D\u9996\u6B21\u8F6C\u8D26\u3002"
