        "zh-Hans": "\u4EC5\u4ECE\u9002\u7528\u4E8E\u6240\u5728\u5730\u533A\u5B9E\u4F53\u7684 Gate \u5B98\u65B9\u57DF\u540D\u5F00\u59CB\uFF0C\u4F7F\u7528\u552F\u4E00\u5BC6\u7801\u521B\u5EFA\u4E2A\u4EBA\u8D26\u6237\uFF0C\u5E76\u6838\u5BF9\u5B9E\u65F6\u53F8\u6CD5\u8F96\u533A\u6761\u6B3E\u3002\u7F51\u9875\u8EAB\u4EFD\u8BA4\u8BC1\u6D41\u7A0B\u8981\u6C42\u56FD\u7C4D\u3001\u5C45\u4F4F\u5730\u3001\u6CD5\u5B9A\u59D3\u540D\u3001\u8BC1\u4EF6\u7C7B\u578B\u4E0E\u53F7\u7801\uFF0C\u968F\u540E\u6309\u8981\u6C42\u5B8C\u6210\u8BC1\u4EF6\u4E0E\u4EBA\u8138\u68C0\u67E5\u3002\u5165\u91D1\u524D\u5E94\u5B8C\u6210\u5B89\u5168\u63A7\u5236\u5E76\u786E\u8BA4\u5145\u503C\u63D0\u73B0\u8D44\u683C\u3002"
