        "zh-Hans": "\u62B5\u62BC\u5C42\u7EA7\u4E0E\u62B5\u62BC\u7387\u76F8\u5173\u4F46\u4E0D\u662F\u540C\u4E00\u63A7\u5236\u3002\u5C42\u7EA7\u628A\u8D44\u4EA7\u6570\u91CF\u5212\u5206\u4E3A\u533A\u95F4\uFF0C\u62B5\u62BC\u7387\u51B3\u5B9A\u8BE5\u4F59\u989D\u53EF\u8D21\u732E\u591A\u5C11\u8BA4\u53EF\u62B5\u62BC\u4EF7\u503C\u3002\u4EFB\u4E00\u53C2\u6570\u53D8\u5316\u65F6\uFF0C\u5373\u4F7F\u5E01\u4EF7\u548C\u540D\u4E49\u4F59\u989D\u4E0D\u53D8\uFF0C\u501F\u8D37\u80FD\u529B\u3001\u8D37\u6B3E\u4EF7\u503C\u6BD4\u4E0E\u5F3A\u5E73\u7F13\u51B2\u4E5F\u53EF\u80FD\u6539\u53D8\u3002\u7528\u6237\u5E94\u5728\u751F\u6548\u524D\u628A\u6BCF\u9879\u8D44\u4EA7\u6620\u5C04\u5230\u4EA7\u54C1\u7279\u5B9A\u5C42\u7EA7\u5E76\u91CD\u7B97\u8D26\u6237\u5065\u5EB7\u5EA6\u3002"
