        "zh-Hans": "\u73B0\u8D27\u4EA4\u6613\u5BF9\u88AB\u79FB\u9664\u4E0D\u4E00\u5B9A\u7B49\u4E8E\u8D44\u4EA7\u88AB\u4E0B\u67B6\uFF0C\u4E24\u79CD\u4E8B\u4EF6\u9700\u8981\u4E0D\u540C\u5904\u7406\u3002Binance \u4E0E OKX \u516C\u544A\u4F1A\u5217\u51FA\u53D7\u5F71\u54CD\u4EA4\u6613\u5BF9\u3001\u6267\u884C\u65F6\u95F4\u548C\u8BA2\u5355\u5904\u7406\uFF0C\u4F46\u7528\u6237\u8FD8\u5FC5\u987B\u5355\u72EC\u786E\u8BA4\u57FA\u7840\u8D44\u4EA7\u80FD\u5426\u901A\u8FC7\u5176\u4ED6\u8BA1\u4EF7\u5E01\u7EE7\u7EED\u4EA4\u6613\uFF0C\u4EE5\u53CA\u5145\u503C\u6216\u63D0\u73B0\u662F\u5426\u4ECD\u7136\u5F00\u653E\u3002\u5B89\u5168\u987A\u5E8F\u662F\u76D8\u70B9\u672A\u6210\u4EA4\u8BA2\u5355\u4E0E\u673A\u5668\u4EBA\uFF0C\u5728\u5E73\u53F0\u622A\u6B62\u524D\u4E3B\u52A8\u64A4\u5355\uFF0C\u9009\u62E9\u5DF2\u6838\u9A8C\u7684\u66FF\u4EE3\u4EA4\u6613\u5BF9\u6216\u6258\u7BA1\u8DEF\u5F84\uFF0C\u5E76\u5728\u53D8\u66F4\u540E\u5BF9\u8D26\u3002"
