        "zh-Hans": "\u6BD4\u7279\u5E01\u540E\u91CF\u5B50\u51C6\u5907\uFF1A\u7814\u8BA8\u4F1A\u7ED3\u8BBA\u3001\u8349\u6848\u63D0\u6848\u4E0E\u771F\u5B9E\u98CE\u9669\u8FB9\u754C"
