        fr: "Fragmentation multicha\xEEne des stablecoins : un ticker ne d\xE9finit pas la route",
        de: "Multichain-Fragmentierung von Stablecoins: Gleiches Ticker, anderer Transferweg",
        ar: "\u062A\u062C\u0632\u0626\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u0642\u0631\u0629 \u0645\u062A\u0639\u062F\u062F\u0629 \u0627\u0644\u0633\u0644\u0627\u0633\u0644: \u0627\u0644\u0631\u0645\u0632 \u0646\u0641\u0633\u0647 \u0644\u0627 \u064A\u0639\u0646\u064A \u0627\u0644\u0645\u0633\u0627\u0631 \u0646\u0641\u0633\u0647",
        ru: "\u041C\u0443\u043B\u044C\u0442\u0438\u0447\u0435\u0439\u043D-\u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u044F \u0441\u0442\u0435\u0439\u0431\u043B\u043A\u043E\u0438\u043D\u043E\u0432: \u043E\u0434\u0438\u043D \u0442\u0438\u043A\u0435\u0440 \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043E\u0434\u0438\u043D \u043F\u0443\u0442\u044C",
