        ar: "\u064A\u0648\u0636\u062D \u062A\u062D\u062F\u064A\u062B \u0631\u0633\u0645\u064A \u0645\u0646 OKX \u062A\u063A\u064A\u064A\u0631 \u0631\u0633\u0648\u0645 \u0627\u0644\u0648\u0627\u062C\u0647\u0629 \u0641\u064A 7 \u0633\u0628\u062A\u0645\u0628\u0631 \u0648\u0627\u0644\u0641\u0631\u0642 \u0628\u064A\u0646\u0647\u0627 \u0648\u0628\u064A\u0646 \u0627\u0644\u063A\u0627\u0632 \u0648\u0631\u0633\u0648\u0645 \u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644 \u0648\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642.",
        ru: "\u041E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 OKX \u043E\u0431\u044A\u044F\u0441\u043D\u044F\u0435\u0442 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 7 \u0441\u0435\u043D\u0442\u044F\u0431\u0440\u044F \u0438 \u043E\u0442\u043B\u0438\u0447\u0438\u0435 \u043A\u043E\u043C\u0438\u0441\u0441\u0438\u0438 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u043E\u0442 \u0433\u0430\u0437\u0430, \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u044C\u043D\u043E\u0439 \u043A\u043E\u043C\u0438\u0441\u0441\u0438\u0438 \u0438 \u043F\u0440\u043E\u0441\u043A\u0430\u043B\u044C\u0437\u044B\u0432\u0430\u043D\u0438\u044F.",
